contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint v1, uint v2) public payable {
        // First SetMinSum before initialization: should succeed and set MinSum.
        c.SetMinSum(v1);
        uint beforeMinSum = c.MinSum();

        // Trigger initialization so the guard becomes active.
        c.Initialized();

        // Second SetMinSum after initialization: must revert, not change MinSum.
        bool reverted;
        try c.SetMinSum(v2) { reverted = false; } catch { reverted = true; }

        uint afterMinSum = c.MinSum();
        assert(reverted && beforeMinSum == v1 && afterMinSum == beforeMinSum);
    }
}

