contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Determine whether the addition block.timestamp + lockTime would overflow.
        // Solidity 0.8+ panics on overflow, which results in a revert.
        bool overflow = lockTime > type(uint256).max - block.timestamp;

        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // General rule: Put reverts iff the addition would overflow;
        // on success, the caller's balance increases by exactly the sent value
        // and the stored unlock time is at least block.timestamp + lockTime (if that is greater than the previous unlockTime).
        assert(
            (reverted == overflow) &&
            (
                reverted ||
                (
                    afterBalance == beforeBalance + amount &&
                    afterUnlock >= beforeUnlock &&
                    (block.timestamp + lockTime > beforeUnlock ? afterUnlock == block.timestamp + lockTime : afterUnlock == beforeUnlock)
                )
            )
        );
    }

    receive() external payable {}
}

