        require(msg.value >= 0);

        // make a deposit so the caller has a positive stored balance
        c.Put{value: msg.value}(_lockTime);

        // read the caller's state BEFORE the deciding call
        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this));

        // try the Collect call and observe whether it reverts
        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }

        // read the caller's state AFTER the call
        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(this));

        // general rule: Collect succeeds exactly when balance >= MinSum and balance >= _am and unlock time has passed;
        // on success balance decreases by exactly _am; on revert balance is unchanged
        if (reverted) {
            assert(balanceAfter == balanceBefore);
        } else {
            assert(balanceAfter == balanceBefore - _am);
            assert(balanceBefore >= _am);
            assert(block.timestamp > unlockTimeBefore);
        }
    }

    receive() external payable {}
}

