        c.Put{value: deposit}(_lockTime);

        // read before-state through public getter only
        (uint unlockBefore, uint balanceBefore) = c.Acc(address(this));

        // deciding call: Collect(_am) must go through public entry
        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }

        // read after-state
        (uint unlockAfter, uint balanceAfter) = c.Acc(address(this));

        // general rule covering both revert and success paths of Collect:
        //  - if Collect reverted, balance must be unchanged
        //  - if Collect succeeded, balance must have decreased by exactly _am
        //    (which implies balanceBefore >= _am and other preconditions held)
        assert(
            (reverted && balanceAfter == balanceBefore) ||
            (!reverted && balanceBefore >= _am && balanceAfter == balanceBefore - _am)
        );
    }

    receive() external payable {}
